```go
// RegistryFieldError reports a structural defect in a registry file: a
// member that is missing, duplicated, unknown or of the wrong type.
// Position is the 1-based record position within "batches" (0 for the root
// object); Batch is set only when the record's batch id can be determined
// unambiguously from a present, well-formed "batch" field.
type RegistryFieldError struct {
	Position int
	Batch    string
	Field    string
	Kind     string // "duplicate", "missing", "unknown", "type"
	Detail   string
}

func (e *RegistryFieldError) Error() string {
	var b strings.Builder
	if e.Position > 0 {
		fmt.Fprintf(&b, "batch record %d", e.Position)
		if e.Batch != "" {
			fmt.Fprintf(&b, " (batch %q)", e.Batch)
		}
		b.WriteString(": ")
	}
	switch e.Kind {
	case "duplicate":
		fmt.Fprintf(&b, "duplicate field %q", e.Field)
	case "missing":
		fmt.Fprintf(&b, "missing required field %q", e.Field)
	case "unknown":
		fmt.Fprintf(&b, "unknown field %q", e.Field)
	case "type":
		fmt.Fprintf(&b, "field %q has wrong type", e.Field)
		if e.Detail != "" {
			fmt.Fprintf(&b, ": %s", e.Detail)
		}
	default:
		b.WriteString(e.Detail)
	}
	return b.String()
}
```

