Now objectMembers:

```go
// objectMembers decodes a single JSON object from raw, returning each
// member's raw value in source order alongside the member names. A name
// appearing more than once (after JSON string unescaping) is a
// *duplicateFieldError; trailing data after the closing brace is rejected.
func objectMembers(raw json.RawMessage) (map[string]json.RawMessage, []string, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	tok, err := dec.Token()
	if err != nil {
		return nil, nil, fmt.Errorf("expected a JSON object: %w", err)
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return nil, nil, errors.New("expected a JSON object")
	}
	fields := make(map[string]json.RawMessage)
	var keys []string
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, nil, err
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, nil, errors.New("object keys must be JSON strings")
		}
		if _, dup := fields[key]; dup {
			return nil, nil, &duplicateFieldError{field: key}
		}
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, nil, err
		}
		fields[key] = value
		keys = append(keys, key)
	}
	if _, err := dec.Token(); err != nil { // closing brace
		return nil, nil, err
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		if err == nil {
			return nil, nil, errors.New("unexpected data after object")
		}
		return nil, nil, err
	}
	return fields, keys, nil
}
```

Now decode:

```go
// allowedRootFields are the only members a registry root object may carry.
var allowedRootFields = map[string]struct{}{
	"version": {}, "batches": {},
}

// allowedBatchFields are the only members a batch record may carry.
var allowedBatchFields = map[string]struct{}{
	"batch": {}, "product": {}, "quantity": {}, "unit": {},
}

func decode(data []byte) (*Registry, error) {
	fields, _, err := objectMembers(data)
	if err != nil {
		var dup *duplicateFieldError
		if errors.As(err, &dup) {
			return nil, &RegistryFieldError{Field: dup.field, Kind: "duplicate"}
		}
		return nil, err
	}
	for name := range fields {
		if _, ok := allowedRootFields[name]; !ok {
			return nil, &RegistryFieldError{Field: name, Kind: "unknown"}
		}
	}
	if _, ok := fields["version"]; !ok {
		return nil, &RegistryFieldError{Field: "version", Kind: "missing"}
	}
	if _, ok := fields["batches"]; !ok {
		return nil, &RegistryFieldError{Field: "batches", Kind: "missing"}
	}

	var version int
	if err := json.Unmarshal(fields["version"], &version); err != nil {
		return nil, &RegistryFieldError{Field: "version", Kind: "type", Detail: "must be JSON integer 1"}
	}
	if version != FormatVersion {
		return nil, fmt.Errorf("unsupported registry version: got %d, want %d", version, FormatVersion)
	}

	batchesRaw := bytes.TrimSpace(fields["batches"])
	if len(batchesRaw) == 0 || batchesRaw[0] != '[' {
		return nil, &RegistryFieldError{Field: "batches", Kind: "type", Detail: "must be a JSON array"}
	}
	var elems []json.RawMessage
	if err := json.Unmarshal(batchesRaw, &elems); err != nil {
		return nil, &RegistryFieldError{Field: "batches", Kind: "type", Detail: "must be a JSON array"}
	}

	reg := &Registry{Version: FormatVersion}
	for i, raw := range elems {
		b, err := decodeBatchRecord(raw, i+1)
		if err != nil {
			return nil, err
		}
		reg.Batches = append(reg.Batches, b)
	}
	return reg, nil
}
```

Now decodeBatchRecord:

```go
// decodeBatchRecord validates one element of the "batches" array. pos is the
// 1-based record position. The record must be a JSON object carrying exactly
// batch, product, quantity and unit, with no duplicated member names; the
// text fields must be non-blank strings and quantity a strict JSON integer
// in 1..MaxQuantity.
func decodeBatchRecord(raw json.RawMessage, pos int) (Batch, error) {
	fields, keys, err := objectMembers(raw)
	if err != nil {
		var dup *duplicateFieldError
		if errors.As(err, &dup) {
			return Batch{}, &RegistryFieldError{Position: pos, Field: dup.field, Kind: "duplicate"}
		}
		return Batch{}, &RegistryFieldError{Position: pos, Detail: err.Error()}
	}
	for _, name := range keys {
		if _, ok := allowedBatchFields[name]; !ok {
			return Batch{}, &RegistryFieldError{Position: pos, Field: name, Kind: "unknown"}
		}
	}
	for _, name := range []string{"batch", "product", "quantity", "unit"} {
		if _, ok := fields[name]; !ok {
			return Batch{}, &RegistryFieldError{Position: pos, Field: name, Kind: "missing"}
		}
	}

	// The batch id is reported alongside errors only when it can be read
	// unambiguously; a missing, duplicated or mistyped "batch" field leaves
	// it blank rather than guessing a value.
	batchID := ""
	if value, ok := fields["batch"]; ok {
		var text string
		if json.Unmarshal(value, &text) == nil {
			if normalized, err := NormalizeField(text); err == nil {
				batchID = normalized
			}
		}
	}

	textField := func(name string) (string, error) {
		var text string
		if err := json.Unmarshal(fields[name], &text); err != nil {
			return "", &RegistryFieldError{Position: pos, Batch: batchID, Field: name, Kind: "type", Detail: "must be a JSON string"}
		}
		normalized, err := NormalizeField(text)
		if err != nil {
			return "", &RegistryFieldError{Position: pos, Batch: batchID, Field: name, Kind: "type", Detail: "must not be blank after trimming"}
		}
		return normalized, nil
	}

	batch, err := textField("batch")
	if err != nil {
		return Batch{}, err
	}
	product, err := textField("product")
	if err != nil {
		return Batch{}, err
	}
	unit, err := textField("unit")
	if err != nil {
		return Batch{}, err
	}
	quantity, err := parseManifestQuantity(bytes.TrimSpace(fields["quantity"]))
	if err != nil {
		return Batch{}, &RegistryFieldError{Position: pos, Batch: batchID, Field: "quantity", Kind: "type", Detail: err.Error()}
	}
	return Batch{Batch: batch, Product: product, Quantity: quantity, Unit: unit}, nil
}
